What does this C program print? (32-bit `int`, 64-bit `long long`, $2^{31}$ = `1LL << 31`.)

```c
#include <stdint.h>
#include <stdio.h>
static int32_t srdhm(int32_t a, int32_t b) {   /* round(a*b / 2^31) */
    int64_t ab = (int64_t)a * b;
    int64_t nudge = ab >= 0 ? (1 << 30) : (1 - (1 << 30));
    return (int32_t)((ab + nudge) / (1LL << 31));
}
int main(void) {
    int32_t m0 = 1374389535;               /* 0.64 * 2^31, rounded */
    printf("%d %d\n", srdhm(10000, m0), srdhm(-10000, m0));
    return 0;
}
```

What does this C program print? (32-bit `int`, arithmetic right shift on negative values, which gcc provides.)

```c
#include <stdint.h>
#include <stdio.h>
static int8_t requant_relu(int32_t acc, int32_t m0, int n, int32_t zp_out) {
    int64_t p = (int64_t)acc * m0;
    int32_t v = (int32_t)((p + (1LL << 30)) >> 31);   /* acc * M0 */
    v = (v + (1 << (n - 1))) >> n;                    /* times 2^-n */
    v += zp_out;
    int32_t lo = zp_out, hi = 127;                    /* ReLU in the clamp */
    return (int8_t)(v < lo ? lo : v > hi ? hi : v);
}
int main(void) {
    printf("%d %d\n", requant_relu(10000, 1374389535, 8, -5), requant_relu(-10000, 1374389535, 8, -5));
    return 0;
}
```

What do the two `printf` lines print? (32-bit `int`; `>>` on negative `int` is an arithmetic shift, as in gcc.)

```c
#include <stdint.h>
#include <stdio.h>
static int32_t rshift_round(int32_t x, int n) {   /* x / 2^n, ties away from 0 */
    int32_t mask = (1 << n) - 1;
    int32_t rem = x & mask;
    int32_t thresh = (mask >> 1) + (x < 0);
    return (x >> n) + (rem > thresh);
}
int main(void) {
    printf("%d %d %d %d\n", 5 >> 1, -5 >> 1, rshift_round(5, 1), rshift_round(-5, 1));
    printf("%d %d\n", rshift_round(6400, 8), rshift_round(-6400, 8));
    return 0;
}
```

Which argument of `quantize_static` gives the weights one scale per output channel, and what does returning `None` from `get_next` mean? (ONNX Runtime static quantization.)

```python
from onnxruntime.quantization import (CalibrationDataReader, QuantFormat,
                                      QuantType, quantize_static)
class Reader(CalibrationDataReader):
    def __init__(self, samples):
        self.it = iter([{"input": s} for s in samples])
    def get_next(self):
        return next(self.it, None)
quantize_static("model.onnx", "model_int8.onnx", Reader(samples),
                quant_format=QuantFormat.QDQ,
                activation_type=QuantType.QInt8, weight_type=QuantType.QInt8,
                per_channel=True)
```
